import type { AreaInventory, AreaLookup, AreaRecord } from "../areaInventory";
import type { CrosswalkInventory } from "../crosswalkInventory";
import type { BoundaryRegistry } from "../boundaryRegistry";
import type { RelationshipCandidateInventory } from "../relationshipCandidates";
import type { AreaRelation, AreaRelationship } from "../areaRelationships";
import type { RelationshipPurpose } from "../relationshipPaths";
import type { AreaIdentity, GeographyEndpoint } from "./areas";
import {
	ConversionCapabilities,
	type GeographyReach,
	type RelationshipOperation,
	type ResolvedConversionPlan,
	type ResolvedRelationshipCapability,
} from "./conversionCapability";
import type { CrosswalkTranslator } from "./translation";
import { releaseKey } from "../geographyKeys";
import { areaId } from "./areas";

export {
	RELATIONSHIP_OPERATIONS,
	type GeographyReach,
	type RelationshipOperation,
	type RelationshipPathStepCoverage,
	type RelationshipPrerequisite,
	type ResolvedConversionPlan,
	type ResolvedRelationshipCapability,
	type ResolvedRelationshipPath,
} from "./conversionCapability";

export type ResolvedRelationshipCoverage = {
	areaCount: number;
	relatedAreaCount: number;
	relationshipCount: number;
	byRelation: Partial<Record<AreaRelation, number>>;
	crosswalkIds: string[];
	uncoveredAreas: Array<AreaRecord & { id: string }>;
};

export type GeographyHealth = {
	geography: string;
	boundaryRelease: string;
	status: "available" | "partial" | "unsupported" | "not-built";
	areaCount: number;
	relatedAreaCount: number;
	gapCount: number;
	countries: string[];
	reach: GeographyReach;
};

export type RelationshipRepair = {
	candidate: RelationshipCandidateInventory["candidates"][number];
	action: "publish-crosswalk" | "review-candidate" | "compile-target-release";
};

type CachedRelationshipCoverage = Omit<
	ResolvedRelationshipCoverage,
	"uncoveredAreas"
> & {
	uncoveredCodes: string[];
};

export type CapabilityResolverInputs = {
	areaInventory?: AreaInventory;
	areaLookup?: AreaLookup;
	crosswalkInventory?: CrosswalkInventory;
	boundaryRegistry?: BoundaryRegistry;
	relationshipCandidateInventory?: RelationshipCandidateInventory;
};

/** Conversion evidence, release coverage, operational health and repair advice. */
export class CapabilityResolver {
	private readonly conversions: ConversionCapabilities;
	private readonly relationshipCoverageCache = new Map<
		string,
		CachedRelationshipCoverage
	>();
	private geographyHealthCache?: GeographyHealth[];
	/** Counts compiled with the crosswalks, read once from the inventory. */
	private compiledCoverage?: Map<
		string,
		Pick<CachedRelationshipCoverage, "areaCount" | "relatedAreaCount">
	>;

	constructor(
		inputs: CapabilityResolverInputs &
			ConstructorParameters<typeof ConversionCapabilities>[0],
		translator: CrosswalkTranslator,
		private readonly relationships: (
			identity: AreaIdentity,
			only?: AreaRelation,
		) => AreaRelationship[],
		private readonly hasRelationships: () => boolean,
		private readonly boundaryRelease: (
			geography: string,
			release: string,
		) => BoundaryRegistry["releases"][number] | undefined,
		/**
		 * The codes of a release that have a relationship, where they can be
		 * found without building the relationships themselves.
		 */
		private readonly relatedCodes?: (
			geography: string,
			release: string,
		) => Set<string>,
	) {
		this.inputs = inputs;
		this.conversions = new ConversionCapabilities(inputs, translator);
	}
	private readonly inputs: CapabilityResolverInputs;

	relationshipCapability(
		from: GeographyEndpoint,
		to: GeographyEndpoint,
		purpose: RelationshipPurpose,
	): ResolvedRelationshipCapability {
		return this.conversions.relationshipCapability(from, to, purpose);
	}
	conversionPlan(
		from: GeographyEndpoint,
		to: GeographyEndpoint,
		purpose: RelationshipPurpose,
		operation?: RelationshipOperation,
	): ResolvedConversionPlan {
		return this.conversions.conversionPlan(from, to, purpose, operation);
	}
	relationshipCapabilitiesFrom(from: GeographyEndpoint) {
		return this.conversions.relationshipCapabilitiesFrom(from);
	}

	relationshipCoverage(
		geography: string,
		boundaryRelease: string,
		relation?: AreaRelation,
		limit = 25,
	): ResolvedRelationshipCoverage | undefined {
		const areas = this.inputs.areaLookup?.get(
			releaseKey(geography, boundaryRelease),
		);
		if (!areas || !this.hasRelationships()) return undefined;
		const key = `${releaseKey(geography, boundaryRelease)}\u0000${relation ?? ""}`;
		let cached = this.relationshipCoverageCache.get(key);
		if (!cached) {
			const byRelation: Partial<Record<AreaRelation, number>> = {};
			const crosswalkIds = new Set<string>();
			let relatedAreaCount = 0;
			let relationshipCount = 0;
			const uncoveredCodes: string[] = [];
			for (const [code] of areas) {
				const relationships = this.relationships(
					{ geography, boundaryRelease, code },
					relation,
				);
				if (relationships.length > 0) {
					relatedAreaCount += 1;
					relationshipCount += relationships.length;
					for (const candidate of relationships) {
						byRelation[candidate.relation] =
							(byRelation[candidate.relation] ?? 0) + 1;
						crosswalkIds.add(candidate.crosswalk.id);
					}
				} else uncoveredCodes.push(code);
			}
			cached = {
				areaCount: areas.size,
				relatedAreaCount,
				relationshipCount,
				byRelation,
				crosswalkIds: [...crosswalkIds].sort(),
				uncoveredCodes,
			};
			this.relationshipCoverageCache.set(key, cached);
		}
		const { uncoveredCodes, ...coverage } = cached;
		return {
			...coverage,
			byRelation: { ...coverage.byRelation },
			crosswalkIds: [...coverage.crosswalkIds],
			uncoveredAreas: uncoveredCodes.slice(0, limit).flatMap((code) => {
				const area = areas.get(code);
				return area
					? [
							{
								id: areaId({
									geography,
									boundaryRelease,
									code,
								}),
								...area,
							},
						]
					: [];
			}),
		};
	}

	/**
	 * How many of a release's areas have a relationship. Health reports this
	 * for every release at once, and everything else in a coverage answer
	 * (counts by relation, crosswalks, the uncovered areas) is built only for
	 * the one release a caller asks about.
	 */
	private relatedAreaCounts(
		geography: string,
		boundaryRelease: string,
	):
		| Pick<CachedRelationshipCoverage, "areaCount" | "relatedAreaCount">
		| undefined {
		const areas = this.inputs.areaLookup?.get(
			releaseKey(geography, boundaryRelease),
		);
		if (!areas || !this.hasRelationships()) return undefined;
		const cached = this.relationshipCoverageCache.get(
			`${releaseKey(geography, boundaryRelease)}\u0000`,
		);
		if (cached) return cached;
		// Counted at build time against the area inventory it names, so the
		// crosswalks are not read. A release whose area count differs was
		// compiled against other areas, and is counted from the crosswalks.
		const compiled = this.compiledCoverageOf(
			releaseKey(geography, boundaryRelease),
		);
		if (compiled && compiled.areaCount === areas.size) return compiled;
		if (!this.relatedCodes)
			return this.relationshipCoverage(
				geography,
				boundaryRelease,
				undefined,
				1,
			);
		const related = this.relatedCodes(geography, boundaryRelease);
		let relatedAreaCount = 0;
		for (const [code] of areas)
			if (related.has(code)) relatedAreaCount += 1;
		return { areaCount: areas.size, relatedAreaCount };
	}

	/** A release's counts compiled with the crosswalks, where they are current. */
	private compiledCoverageOf(release: string) {
		if (!this.compiledCoverage) {
			const compiled = this.inputs.crosswalkInventory?.releaseCoverage;
			this.compiledCoverage = new Map(
				compiled !== undefined &&
					compiled.areaInventoryHash ===
						this.inputs.areaInventory?.contentHash
					? compiled.releases.map((coverage) => [
							releaseKey(
								coverage.geography,
								coverage.boundaryRelease,
							),
							coverage,
						])
					: [],
			);
		}
		return this.compiledCoverage.get(release);
	}

	geographyHealth(): GeographyHealth[] {
		if (!this.inputs.areaLookup) return [];
		if (this.geographyHealthCache) return [...this.geographyHealthCache];
		const reach = this.conversions.conversionReach();
		this.geographyHealthCache = [...this.inputs.areaLookup.keys()]
			.map((identity) => {
				const [geography, boundaryRelease] = identity.split("/", 2) as [
					string,
					string,
				];
				const coverage = this.relatedAreaCounts(
					geography,
					boundaryRelease,
				);
				const areaCount =
					this.inputs.areaLookup?.get(identity)?.size ?? 0;
				const countries =
					this.boundaryRelease(geography, boundaryRelease)?.coverage
						.countries ?? [];
				const found = reach.get(identity) ?? {
					status: "isolated" as const,
					reaches: [],
					reachedFrom: [],
					vintagePathCount: 0,
				};
				if (!coverage)
					return {
						geography,
						boundaryRelease,
						status: "not-built" as const,
						areaCount,
						relatedAreaCount: 0,
						gapCount: areaCount,
						countries,
						reach: found,
					};
				return {
					geography,
					boundaryRelease,
					status:
						coverage.relatedAreaCount === coverage.areaCount
							? ("available" as const)
							: coverage.relatedAreaCount > 0
								? ("partial" as const)
								: ("unsupported" as const),
					areaCount: coverage.areaCount,
					relatedAreaCount: coverage.relatedAreaCount,
					gapCount: coverage.areaCount - coverage.relatedAreaCount,
					countries,
					reach: found,
				};
			})
			.sort((left, right) =>
				releaseKey(left.geography, left.boundaryRelease).localeCompare(
					releaseKey(right.geography, right.boundaryRelease),
				),
			);
		return [...this.geographyHealthCache];
	}

	relationshipRepairs(): RelationshipRepair[] {
		const actionFor = (
			candidate: RelationshipRepair["candidate"],
		): RelationshipRepair["action"] =>
			candidate.status === "eligible"
				? "publish-crosswalk"
				: candidate.status === "needs-review"
					? "review-candidate"
					: "compile-target-release";
		const order = {
			"publish-crosswalk": 0,
			"review-candidate": 1,
			"compile-target-release": 2,
		} as const;
		return (this.inputs.relationshipCandidateInventory?.candidates ?? [])
			.filter((candidate) => !candidate.publishedCrosswalkId)
			.map((candidate) => ({ candidate, action: actionFor(candidate) }))
			.sort(
				(left, right) =>
					order[left.action] - order[right.action] ||
					left.candidate.id.localeCompare(right.candidate.id),
			);
	}
}
